CREATE TABLE IF NOT EXISTS github_links (member_id VARCHAR(36) PRIMARY KEY, team_id VARCHAR(36) NOT NULL, github_user_id BIGINT NOT NULL, github_login VARCHAR(39) NOT NULL, client_id VARCHAR(64) NOT NULL, credential text NOT NULL, `state` VARCHAR(24) NOT NULL, access_expires_at BIGINT NULL, refresh_expires_at BIGINT NULL, token_version INT NOT NULL, refresh_pending BOOLEAN DEFAULT FALSE NOT NULL, refresh_started_at BIGINT DEFAULT 0 NOT NULL, linked_at BIGINT NOT NULL, refreshed_at BIGINT NOT NULL, CONSTRAINT github_links_member FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE, CONSTRAINT github_links_team FOREIGN KEY (team_id) REFERENCES teams(id));
ALTER TABLE github_links ADD CONSTRAINT github_link_user UNIQUE (team_id, github_user_id);